import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.C2TvIV46.js";const g=JSON.parse('{"title":"References","description":"","frontmatter":{},"headers":[],"relativePath":"language/references.md","filePath":"language/references.md"}'),o={name:"language/references.md"};function l(r,e,c,d,p,i){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h1><p>Megalo actions and conditions take <strong>operands</strong> — values that identify players, teams, objects, timers, and variables at runtime. This page describes the reference model: how operands are written and what they resolve to.</p><h2 id="reference-types" tabindex="-1">Reference types <a class="header-anchor" href="#reference-types" aria-label="Permalink to &quot;Reference types&quot;">​</a></h2><p>Megalo has five typed reference kinds:</p><table tabindex="0"><thead><tr><th>Type</th><th>Holds</th><th>Example</th></tr></thead><tbody><tr><td>Player</td><td>A player slot</td><td><code>current_player</code>, <code>killer</code>, <code>none</code></td></tr><tr><td>Team</td><td>A team</td><td><code>current_team</code>, <code>attackers</code>, <code>defenders</code>, <code>none</code></td></tr><tr><td>Object</td><td>A map object</td><td><code>current_object</code>, <code>one_flag</code>, <code>none</code></td></tr><tr><td>Timer</td><td>A countdown timer</td><td><code>round_timer</code>, <code>current_player.game_start_vo</code></td></tr><tr><td>Number</td><td>An integer value</td><td><code>my_counter</code>, <code>score_to_win_round</code>, <code>0</code></td></tr></tbody></table><p>Each type has a <code>none</code> sentinel meaning &quot;no reference&quot; or &quot;empty.&quot;</p><h2 id="context-references" tabindex="-1">Context references <a class="header-anchor" href="#context-references" aria-label="Permalink to &quot;Context references&quot;">​</a></h2><p>Built-in refs for the current evaluation context and related engine state:</p><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Availability</th></tr></thead><tbody><tr><td><code>current_player</code></td><td>Player</td><td>Inside <code>player</code> triggers</td></tr><tr><td><code>current_team</code></td><td>Team</td><td>Inside <code>team</code> triggers</td></tr><tr><td><code>current_object</code></td><td>Object</td><td>Inside <code>object</code> / map-object-filter triggers</td></tr><tr><td><code>local_player</code></td><td>Player</td><td>Always</td></tr><tr><td><code>local_team</code></td><td>Team</td><td>Always (team that owns <code>local_player</code>)</td></tr><tr><td><code>target_player</code></td><td>Player</td><td>Always (HUD target player)</td></tr><tr><td><code>target_object</code></td><td>Object</td><td>Always (HUD target object)</td></tr><tr><td><code>target_team</code></td><td>Team</td><td>MegaloEvolved extension <code>targetTeam</code> (team that owns <code>target_player</code>)</td></tr></tbody></table><p><code>current_*</code> refs are gated by trigger depth. The others are always available.</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-enumMember">local</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">local_team</span><span class="megalo-text"> </span><span class="megalo-keyword">equal_to</span><span class="megalo-text"> </span><span class="megalo-variable">attackers</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">hud_widget_set_visibility</span><span class="megalo-text"> status_widget </span><span class="megalo-variable">local_player</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>See also <a href="/MegaloEvolved/beta/docs/language/enums/built-in-variables">Built-in variables</a>.</p><h2 id="custom-variable-references" tabindex="-1">Custom variable references <a class="header-anchor" href="#custom-variable-references" aria-label="Permalink to &quot;Custom variable references&quot;">​</a></h2><p>Variables declared in <code>variables</code> blocks are referenced by name. Member variables use dot notation:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-comment">; global variable</span></span>
<span class="line"><span class="megalo-text">action set sudden_death_condition set_to true</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">; player member variable</span></span>
<span class="line"><span class="megalo-text">action set current_player</span><span class="megalo-operator">.</span><span class="megalo-text">is_leader set_to </span><span class="megalo-number">1</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">; team member variable</span></span>
<span class="line"><span class="megalo-text">action set current_team</span><span class="megalo-operator">.</span><span class="megalo-text">goal set_to current_object</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">; object member variable</span></span>
<span class="line"><span class="megalo-text">action timer_set_rate buy_zone</span><span class="megalo-operator">.</span><span class="megalo-text">phase_1_timer </span><span class="megalo-number">1</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">; chained member access</span></span>
<span class="line"><span class="megalo-text">action set buy_zone</span><span class="megalo-operator">.</span><span class="megalo-text">allies_present set_to attackers_in_area</span></span></code></pre></div><h2 id="team-designators" tabindex="-1">Team designators <a class="header-anchor" href="#team-designators" aria-label="Permalink to &quot;Team designators&quot;">​</a></h2><p>Teams can be referenced by their designator name:</p><table tabindex="0"><thead><tr><th>Designator</th><th>Role</th></tr></thead><tbody><tr><td><code>attackers</code></td><td>Attacking team</td></tr><tr><td><code>defenders</code></td><td>Defending team</td></tr><tr><td><code>third_party</code></td><td>Third team</td></tr><tr><td><code>fourth_party</code></td><td>Fourth team</td></tr><tr><td><code>fifth_party</code></td><td>Fifth team</td></tr><tr><td><code>sixth_party</code></td><td>Sixth team</td></tr><tr><td><code>seventh_party</code></td><td>Seventh team</td></tr><tr><td><code>eighth_party</code></td><td>Eighth team</td></tr><tr><td><code>none</code></td><td>No team</td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action play_sound team defenders bone_cv_ph1_intro</span></span>
<span class="line"><span class="megalo-text">action set_score add </span><span class="megalo-number">1</span><span class="megalo-text"> team attackers</span></span>
<span class="line"><span class="megalo-text">condition if current_player</span><span class="megalo-operator">.</span><span class="megalo-text">team equal_to attackers</span></span></code></pre></div><p>Team designators are assigned in <code>teams</code> blocks:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">teams</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">team</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-parameter">designator</span><span class="megalo-text"> </span><span class="megalo-enumMember">defenders</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">team</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-parameter">designator</span><span class="megalo-text"> </span><span class="megalo-enumMember">attackers</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="team-or-player-target" tabindex="-1">Team or player target <a class="header-anchor" href="#team-or-player-target" aria-label="Permalink to &quot;Team or player target&quot;">​</a></h2><p>Some actions take a <strong>team or player target</strong> — a specific player, a specific team, or everyone. Syntax is <code>team &lt;team_ref&gt;</code>, <code>player &lt;player_ref&gt;</code>, or <code>everyone</code>. See <a href="/MegaloEvolved/beta/docs/language/enums/team-or-player-target">Team or player target</a> for the full operand reference.</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action set_score add </span><span class="megalo-number">1</span><span class="megalo-text"> team attackers</span></span>
<span class="line"><span class="megalo-text">action play_sound team defenders bone_cv_ph1_intro</span></span>
<span class="line"><span class="megalo-text">action hud_post_message everyone none </span><span class="megalo-string">&quot;Round started!&quot;</span></span></code></pre></div><h2 id="audience-references" tabindex="-1">Audience references <a class="header-anchor" href="#audience-references" aria-label="Permalink to &quot;Audience references&quot;">​</a></h2><p>Other actions take an <strong>audience</strong> operand that specifies who is affected (visibility, pickup filters, and similar):</p><table tabindex="0"><thead><tr><th>Audience</th><th>Meaning</th></tr></thead><tbody><tr><td><code>everyone</code></td><td>All players</td></tr><tr><td><code>allies</code></td><td>Friendly players (relative to context)</td></tr><tr><td><code>enemies</code></td><td>Enemy players</td></tr><tr><td><code>player</code></td><td>A specific player (followed by the player ref)</td></tr><tr><td><code>team</code></td><td>A specific team (followed by the team ref)</td></tr><tr><td><code>no_one</code></td><td>Nobody</td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action navpoint_set_visible current_object allies</span></span>
<span class="line"><span class="megalo-text">action set_pickup_filter one_flag enemies</span></span>
<span class="line"><span class="megalo-text">action boundary_set_visible capture_zone everyone</span></span></code></pre></div><h2 id="built-in-timer-references" tabindex="-1">Built-in timer references <a class="header-anchor" href="#built-in-timer-references" aria-label="Permalink to &quot;Built-in timer references&quot;">​</a></h2><p>The engine provides built-in timers that are not declared in <code>variables</code> blocks:</p><table tabindex="0"><thead><tr><th>Timer</th><th>Description</th></tr></thead><tbody><tr><td><code>round_timer</code></td><td>Elapsed time in the current round</td></tr><tr><td><code>sudden_death_timer</code></td><td>Sudden death countdown</td></tr><tr><td><code>grace_period_timer</code></td><td>Grace period after round time expires</td></tr></tbody></table><p>Custom timers are declared as <code>networked timer</code> variables and referenced by name or through member access.</p><h2 id="object-type-references" tabindex="-1">Object type references <a class="header-anchor" href="#object-type-references" aria-label="Permalink to &quot;Object type references&quot;">​</a></h2><p>Object types in <code>create_object</code> and <code>object_is_type</code> use quoted names from <a href="/MegaloEvolved/beta/docs/language/object-lists">object lists</a>:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action create_object </span><span class="megalo-string">&quot;flag&quot;</span><span class="megalo-text"> at current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag_spawn set current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag never_garbage</span></span>
<span class="line"><span class="megalo-text">action create_object </span><span class="megalo-string">&quot;invis_cov_resupply_capsule&quot;</span><span class="megalo-text"> at current_object never_garbage</span></span>
<span class="line"><span class="megalo-text">condition object_is_type current_object </span><span class="megalo-string">&quot;area&quot;</span></span>
<span class="line"><span class="megalo-text">condition object_is_type current_object </span><span class="megalo-string">&quot;fireteam_1_respawn_zone&quot;</span></span></code></pre></div><h2 id="player-as-object-references" tabindex="-1">Player-as-object references <a class="header-anchor" href="#player-as-object-references" aria-label="Permalink to &quot;Player-as-object references&quot;">​</a></h2><p>A player reference can be used wherever an object reference is expected. The engine resolves the player&#39;s physical body object:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-comment">; from simple/koth/1.txt — a player reference used as an object reference</span></span>
<span class="line"><span class="megalo-text">action for_each player</span></span>
<span class="line"><span class="megalo-text">	condition object_in_area current_player current_object</span></span>
<span class="line"><span class="megalo-text">	action timer_set_rate current_player</span><span class="megalo-operator">.</span><span class="megalo-text">time_in_hill </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">temporary object my_body current_player</span></span>
<span class="line"><span class="megalo-text">action for_each general</span></span>
<span class="line"><span class="megalo-text">	condition if my_body </span><span class="megalo-operator">!=</span><span class="megalo-text"> none</span></span>
<span class="line"><span class="megalo-text">	action set current_player</span><span class="megalo-operator">.</span><span class="megalo-text">body </span><span class="megalo-operator">=</span><span class="megalo-text"> my_body</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="string-table-references" tabindex="-1">String table references <a class="header-anchor" href="#string-table-references" aria-label="Permalink to &quot;String table references&quot;">​</a></h2><p>String operands in actions and element fields reference symbols defined in <code>string_table</code> blocks:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action hud_post_message player current_player none invasion_title_spartan</span></span>
<span class="line"><span class="megalo-text">action player_set_objective current_player slayer_objective score_to_win_round</span></span>
<span class="line"><span class="megalo-text">action navpoint_set_text current_object nav_weapon_drop</span></span></code></pre></div><p>These are not quoted strings in the source — they are identifier references resolved through the string table at runtime. When the string contains <code>%</code> placeholders, following operands fill those slots — see <a href="/MegaloEvolved/beta/docs/language/enums/dynamic-strings">Dynamic strings</a>.</p><h2 id="filter-references" tabindex="-1">Filter references <a class="header-anchor" href="#filter-references" aria-label="Permalink to &quot;Filter references&quot;">​</a></h2><p>Object filter operands identify who can interact with an object:</p><table tabindex="0"><thead><tr><th>Filter</th><th>Meaning</th></tr></thead><tbody><tr><td><code>all</code></td><td>Everyone</td></tr><tr><td><code>allies</code></td><td>Friendly players/teams</td></tr><tr><td><code>enemies</code></td><td>Enemy players/teams</td></tr><tr><td><code>no_one</code></td><td>Nobody</td></tr><tr><td><code>none</code></td><td>No filter (disabled)</td></tr></tbody></table><p>Used in respawn, pickup, and fireteam filter actions:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action set_respawn_filter current_object allies</span></span>
<span class="line"><span class="megalo-text">action set_pickup_filter current_object no_one</span></span>
<span class="line"><span class="megalo-text">action set_fireteam_respawn_filter current_object all</span></span></code></pre></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/language/variable-model">Variable model</a> — declaring custom variables</li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger/action">action</a> — how references appear as operands</li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger/condition">condition</a> — references in comparisons</li><li><a href="/MegaloEvolved/beta/docs/language/object-lists">Object lists</a> — symbolic names for object types and incidents</li></ul>`,49)])])}const b=a(o,[["render",l]]);export{g as __pageData,b as default};
